<?php if ($quotes): ?><div class="tbl-wrap"><table class="tbl"><thead><tr><th>N°</th><th>Date</th><th>Statut</th><th class="right">Montant</th><th></th></tr></thead><tbody><?php foreach ($quotes as $q): ?><tr><td><b><?= e($q['ref']) ?></b></td><td><?= fdate($q['created_at']) ?></td><td><?= status_badge(QUOTE_STATUS, $q['status']) ?></td><td class="right"><?= $q['total'] ? money($q['total']) : '—' ?></td><td><a class="btn btn-p btn-sm" href="/devis/<?= e($q['ref']) ?>">Ouvrir</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php else: ?><div class="panel center"><p class="muted">Aucune demande de devis.</p><a class="btn btn-a" href="/devis">Demander un devis</a></div><?php endif; ?>
